{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO no-fault eviction relocation assistance","requirement":"A landlord may evict a tenant without fault from an RSO unit only for a listed no-fault reason, after filing a Declaration of Intent to Evict with LAHD and serving notice, and must pay relocation assistance within 15 days.","key_value":"Eligible tenant $11,000 (under 3 years) / $14,400 (3+ years or low income); qualified tenant $23,150 / $27,400 (7/1/2026-6/30/2027)","coverage_conditions":"Rental units covered by the Rent Stabilization Ordinance (RSO).","applicability":{"conditions":[],"per_tenancy":"Relocation amount depends on whether the tenant is eligible or qualified, length of tenancy and income; single payment per unit split pro rata among tenants.","coverage_quotes":[]},"exemptions":"Replacing a resident manager with another resident manager; eviction required by hazardous conditions from a natural disaster not caused by landlord negligence; landlord may offset accumulated rent against relocation assistance except for government orders to vacate.","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the RSO; tenant may raise non-payment as an affirmative defense and seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":"RSO relocation amounts must be enhanced for lower income tenants under the State Housing Crisis Act.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles JCO no-fault eviction relocation assistance","requirement":"A landlord may end a JCO tenancy without fault only for a listed reason, must file a Declaration of Intent to Evict with LAHD before serving notice, and must pay relocation assistance within 15 days.","key_value":"Eligible tenant $11,000 / $14,400; qualified tenant $23,150 / $27,400 (7/1/2026-6/30/2027); one month's rent for owner move-in at qualifying single-family dwellings","coverage_conditions":"Rental units covered by the Just Cause Ordinance (JCO).","applicability":{"conditions":[],"per_tenancy":"Single-family dwelling subject to the JCO owned by a natural person who owns no more than four dwelling units and a single-family home on a separate lot: one month's rent for owner, relative or manager move-in.","coverage_quotes":[]},"exemptions":"Replacing a resident manager with another resident manager; eviction required by hazardous conditions from a natural disaster not caused by landlord negligence; landlord may offset accumulated rent against relocation assistance except for government orders to vacate.","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the JCO; tenant may raise non-payment as an affirmative defense and seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"Payment shall be made available within fifteen (15) days of service of the written notice of eviction","interaction":"RSO and JCO relocation amounts must be enhanced for lower income tenants under the State Housing Crisis Act.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Resident Protections Ordinance demolition relocation","requirement":"An owner who demolishes a Protected Unit for new construction within 5 years of filing the Notice of Intent to Withdraw or Declaration of Intent to Evict must provide relocation and RPO occupant protections, paying the highest of State and City amounts.","key_value":"$250,000 per displaced unit penalty","coverage_conditions":"Protected Units - rent-restricted, rent-controlled, lower-income, or Ellis-Act-withdrawn units - demolished for new construction.","applicability":{"conditions":[{"type":"other","text":"Protected Units: units rent-restricted, rent-controlled, lower-income, or Ellis-Act-withdrawn in the past 5-10 years"}],"per_tenancy":"Applies only to Protected Units demolished for new construction.","coverage_quotes":["Protected Units: (1) Residential dwelling units that are or were subject to a recorded covenant, ordinance, or law that restricts rents to levels affordable to persons and families of lower or very low income within the past five years."]},"exemptions":"The regular RSO or JCO relocation rules apply if the units are not Protected Units or are not occupied by a lower income tenant.","penalty":"Financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","valid_through":null,"citation":"Resident Protections Ordinance (RPO)","quoted_span":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","interaction":"Owner must pay the highest of the applicable State (HCA) and City relocation amounts.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","n_rules":3,"note":null}

